// ── WF4: Validar formulario de retroalimentación ─────────────────────────
const b = $json;
const errors = [];
const required = ['student_id', 'student_name', 'course_id', 'task_id', 'grade', 'feedback_text'];
required.forEach(f => { if (b[f] === undefined || b[f] === null || b[f] === '') errors.push('Campo requerido: ' + f); });
if (b.grade !== undefined) {
  const g = Number(b.grade);
  if (isNaN(g) || g < 0 || g > 100) errors.push('Nota debe estar entre 0 y 100 (recibido: ' + b.grade + ')');
}
if (errors.length > 0) return [{ json: { valid: false, errors, status: 'error' } }];

const grade = Number(b.grade);
const needsAlert = grade < 60;
const feedbackType = grade >= 80 ? 'positive' : grade >= 60 ? 'neutral' : 'negative';
const studentEmail = b.student_email || ('estudiante.' + String(b.student_id).toLowerCase() + '@academico.local');
const safe = s => String(s||'').replace(/'/g,"''");

const sql_feedback =
  "INSERT INTO feedback (student_id, student_name, course_id, task_id, grade, feedback_text, feedback_type, sent_notification) VALUES (" +
  "'" + safe(b.student_id) + "','" + safe(b.student_name) + "','" + safe(b.course_id) + "','" + safe(b.task_id) + "'," +
  grade + ",'" + safe(b.feedback_text) + "','" + feedbackType + "'," + (needsAlert ? 'TRUE' : 'FALSE') + ") RETURNING id";

return [{ json: { ...b, grade, needsAlert, feedbackType, studentEmail, valid: true, sql_feedback } }];

// ── WF4: Preparar email de retroalimentación ─────────────────────────────
const j = $json;
const grade = Number(j.grade);
const isLow = grade < 60;
const hdrColor = isLow ? '#dc2626' : grade < 80 ? '#d97706' : '#16a34a';
const icon = isLow ? '⚠️' : grade < 80 ? '📝' : '🎉';
const gradeLabel = isLow ? 'Reprobado' : grade < 80 ? 'Aprobado' : 'Excelente';

const emailSubject = icon + ' Retroalimentación: ' + j.task_name_label || j.task_id + ' (' + grade + '/100)';
const emailBody = `
<div style="font-family:'Segoe UI',Arial,sans-serif;max-width:580px;margin:0 auto">
  <div style="background:linear-gradient(135deg,${hdrColor},${hdrColor}99);color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">
    <h2 style="margin:0">${icon} Retroalimentación Académica</h2>
    <p style="margin:6px 0 0;opacity:.9">Tarea: ${j.task_id} — Curso: ${j.course_id}</p>
  </div>
  <div style="background:#fff;padding:24px;border:1px solid #e2e8f0;border-top:none;border-radius:0 0 10px 10px">
    <p>Estimado/a <strong>${j.student_name}</strong>,</p>
    <p style="margin-top:12px">Hemos registrado su calificación y retroalimentación:</p>
    <div style="background:#f8fafc;border-radius:8px;padding:16px;margin:16px 0;text-align:center">
      <div style="font-size:3em;font-weight:800;color:${hdrColor}">${grade}<span style="font-size:.5em;color:#64748b">/100</span></div>
      <div style="color:${hdrColor};font-weight:600;font-size:14px">${gradeLabel}</div>
    </div>
    <div style="background:#f8fafc;border-radius:8px;padding:16px;border-left:4px solid ${hdrColor};margin-bottom:16px">
      <p style="font-weight:600;color:#374151;margin-bottom:6px">💬 Comentarios del docente:</p>
      <p style="color:#4b5563;font-size:14px">${j.feedback_text}</p>
    </div>
    ${isLow ? '<p style="color:#dc2626;font-size:13px;font-weight:600">⚠️ Su nota está por debajo del mínimo aprobatorio (60). Por favor comuníquese con su docente para asesoría académica.</p>' : ''}
  </div>
</div>`;

const safe = s => String(s||'').replace(/'/g,"''");
const notif_sql = "INSERT INTO notifications_log (student_id, notification_type, message, status) VALUES ('" +
  safe(j.student_id) + "', 'feedback_alert', 'Retroalimentacion enviada. Nota: " + grade + "/100 (" + gradeLabel + ")', 'sent')";

return [{ json: { ...j, emailSubject, emailBody, notif_sql } }];

