// ── WF4: Construir respuesta del webhook ──────────────────────────────────
const j = $json;
return [{
  json: {
    success: true,
    student_id: j.student_id,
    task_id: j.task_id,
    grade: j.grade,
    feedbackType: j.feedbackType,
